class Base {
    public:
        virtual void virtFunc();  // Compiler synthesizes a vptr as the first member of the object layout
        int dataMember;  // Follows vptr in memory, with possible padding for alignment (e.g., 4-byte align on 32-bit systems)
};  // For Derived : public Base, the compiler creates a new vtable overriding Base's entries

code_example:
#include <iostream>

class Base {
public:
    virtual void virtFunc() { std::cout << "Base::virtFunc called"; }  // Virtual function entry in vtable
};

class Derived : public Base {
public:
    void virtFunc() override { std::cout << "Derived::virtFunc called"; }  // Overrides entry in Derived's vtable
};

int main() {
    Derived d;  // Object 'd' includes a vptr pointing to Derived's vtable
    Base* b = &d;  // Pointer to Base, but runtime dispatch uses d's vptr
    b->virtFunc();  // Compiler generates code to dereference vptr and call via vtable
    return 0;
}
